    'tour_owner_step_domains_title' => 'মেনু',
    'tour_owner_step_domains_loc' => 'বাম পাশে (ফোনে মেনুর বোতাম)',
    'tour_owner_step_domains_body' => 'একটাই তালিকা, চার ভাগে: প্রতিদিনের কাজ, টাকা, পণ্য ও পার্টনার, তারপর স্টাফ, রিপোর্ট, ওয়েবসাইট ও সেটিংস। এক সারিতে কয়েকটি পাতা থাকলে পাতার ওপরে ট্যাব হয়ে আসে।',
    'tour_owner_step_domains_action' => 'সারিতে চেপে খুলুন। পাতা খুঁজতে “মেনু খুঁজুন”-এ লিখুন।',
    'tour_owner_step_domains_tip' => 'টাকা তোলার অনুরোধ এবং কমিশনের নিয়ম ও হার আলাদা সারি। কম লাগে এমন পাতা সেটিংসে।',
    'tour_staff_step_domains_title' => 'মেনু',
    'tour_staff_step_domains_loc' => 'বাম পাশে (ফোনে মেনুর বোতাম)',
    'tour_staff_step_domains_body' => 'একটাই তালিকা, প্রতিদিনের কাজ আগে। আপনার কাজের সারি ও ট্যাবই শুধু দেখবেন। এক সারিতে কয়েকটি পাতা থাকলে পাতার ওপরে ট্যাব হয়ে আসে।',
    'tour_staff_step_domains_action' => 'সারিতে চেপে খুলুন। পাতা খুঁজতে “মেনু খুঁজুন”-এ লিখুন।',
    'tour_staff_step_domains_tip' => 'সারির পাশে সংখ্যা মানে সেখানে কাজ অপেক্ষায় আছে। কোনো পাতা না পেলে মালিকের কাছে অনুমতি চান।',
    'tour_office_treasury_title' => 'ট্রেজারি: কোম্পানির সব টাকা',
    'tour_office_treasury_loc' => 'মেনু → ট্রেজারি',
    'tour_office_treasury_body' => 'কোম্পানির টাকার একটাই জায়গা। ফান্ডে দেখবেন কত এসেছে, কত গেছে, এখন কত আছে। অর্ডারের হিসাবে প্রতি অর্ডারে এক সারি। “অন্যান্য মডিউল” পাতার ঘটনার খাতায় সবকিছু সময় ধরে। পার্টনারদের টাকায় কার কত আছে। টাকার কাজে যা অপেক্ষায় আছে।',
    'tour_office_treasury_action' => 'মেনুতে “ট্রেজারি” চাপুন, তারপর ওপরের ট্যাব চাপুন।',
    'tour_office_treasury_tip' => 'টাকার সব হিসাব ডেলিভারির পরে হয়।',
    'tour_office_settings_title' => 'সেটিংস',
    'tour_office_settings_loc' => 'মেনু → সেটিংস (শেষ সারি)',
    'tour_office_settings_body' => 'লিংকের একটি পাতা, তিন ভাগে: টাকা, এলাকা ও পার্টনার, সিস্টেম। হিসাবের নিয়ম, বিকাশ ও ব্যাংক নম্বর, লগইনের নিয়ম, কুরিয়ার সংযোগ আর কাজের রেকর্ড এখানে।',
    'tour_office_settings_action' => '“সেটিংস” চেপে একটি লিংক চাপুন।',
    'tour_office_settings_tip' => 'যে লিংক খুলতে পারবেন, শুধু সেটাই দেখবেন।',
    'tour_partner_buy_title' => 'এখান থেকে শুরু: নতুন অর্ডার',
    'tour_partner_buy_loc' => 'আপনার অ্যাকাউন্টের পাশের শর্টকাট বোতাম (ফোনে নিচে)',
    'tour_partner_buy_body' => 'প্রতিদিনের কাজের দ্রুত বোতাম: নতুন অর্ডার, আমার অর্ডার, ডেলিভারি, ওয়ালেট ও আরও।',
    'tour_partner_buy_action' => '“নতুন অর্ডার” চেপে পণ্য বেছে অর্ডার পাঠান। পুরো টাকা আগে দিন: বিকাশ, নগদ, রকেট বা ব্যাংকে পাঠিয়ে প্রমাণ দিন, অফিসে নগদ দিন, অথবা আপনার অ্যাকাউন্টের টাকা থেকে কাটান।',
    'tour_partner_buy_tip' => 'পণ্য শুধু কোম্পানি থেকে কিনবেন। পুরো টাকা যাচাই হলে তবেই পণ্য পাঠানো হয়।',
    'tour_partner_income_title' => 'খাতে খাতে আপনার আয়',
    'tour_partner_income_loc' => 'শর্টকাট বোতামের নিচে',
    'tour_partner_income_body' => 'প্রতিটি আয়ের খাতের একটি করে নাম, যেমন “নিজের কেনার আয়” ও “রেফারেল আয় (সরাসরি)”, এ পর্যন্ত মোট কত।',
    'tour_partner_income_action' => 'কার্ডে চাপলে ওয়ালেটে শুধু ওই আয়ের তালিকা খোলে।',
    'tour_partner_income_tip' => 'সব আয়ের খাত এক জায়গায় দেখতে “আমার অ্যাকাউন্ট” খুলুন। যে খাতে টাকা আসেনি, সেখানে ৳০.০০ দেখাবে।',
    'tour_partner_sidebar_title' => 'মেনু',
    'tour_partner_sidebar_loc' => 'বাম পাশে (ফোনে মেনুর বোতাম)',
    'tour_partner_sidebar_body' => 'সব পাতা: নতুন অর্ডার, আমার অর্ডার, ওয়ালেট, আমার টিম, অফিসে যোগাযোগ, আমার অ্যাকাউন্ট ও অন্যান্য মডিউল। প্রেসক্রিপশন সবসময় মেনুতে থাকে।',
    'tour_partner_sidebar_action' => 'সারিতে চেপে খুলুন। এক সারিতে কয়েকটি পাতা থাকলে ওপরে ট্যাব হয়ে আসে। পাতা খুঁজতে “মেনু খুঁজুন”-এ লিখুন।',
    'tour_partner_sidebar_tip' => 'আটকে গেলে অফিসে যোগাযোগ → সাহায্য পাতায় নির্দেশিকা ও সাহায্যের ফর্ম আছে।',
    'getting_started_s1' => 'নিজের প্যানেলের ঠিকানা চিনে নিন। মালিকের ঠিকানা শুরু হয় sadmin দিয়ে, স্টাফের manage, ডিলারের dealer আর সাব-ডিলারের subdealer দিয়ে।',
    'getting_started_s2' => 'লগইন পাতায় ইমেইল বা ফোন নম্বর লিখুন, তারপর পাসওয়ার্ড লিখে “লগইন” চাপুন। ডিলার ও সাব-ডিলার নিজের কোডও লিখতে পারেন।',
    'getting_started_s3' => 'ফোনে বা অ্যাপে কোড এলে সেই কোডটি লিখুন।',
    'getting_started_s4' => 'নতুন অ্যাকাউন্টে অফিস একটি অস্থায়ী পাসওয়ার্ড দেয়। প্রথমবার ঢুকলে নিরাপত্তা পাতা নিজে খুলবে। সেখানে নিজের নতুন পাসওয়ার্ড দিন।',
    'getting_started_s5' => 'প্রথমবার ড্যাশবোর্ডে একটি ছোট ট্যুর আসতে পারে। শেষ পর্যন্ত দেখে নিন।',
    'getting_started_s6' => 'ওপরের বারে আপনার নাম, ভাষা বদলের বাটন আর দিন-রাতের বাটন দেখুন। শুরুতে দিনের (হালকা) মোড চালু থাকে।',
    'getting_started_s7' => 'ড্যাশবোর্ডের সংখ্যাগুলো দেখুন। আগে কিছু শেষ করতে হলে ওপরে একটি বার্তা আসবে।',
    'getting_started_s8' => 'শুধু নিজের প্যানেলের ঠিকানা বুকমার্ক করুন। মালিকের পাসওয়ার্ড কখনো স্টাফ প্যানেলে দেবেন না।',
    'getting_started_s9' => 'লগইন না হলে ঠিকানা ও পাসওয়ার্ড আবার দেখুন। দরকার হলে “পাসওয়ার্ড ভুলে গেছেন?” চাপুন। অ্যাকাউন্ট বন্ধ (স্থগিত) থাকলে অফিসে ফোন করুন। স্টাফ হলে দেখুন মালিক আপনাকে অনুমতি দিয়েছেন কিনা।',
    'getting_started_o1' => 'আপনি নিজের প্যানেলে ঢুকেছেন এবং নিজের কাজের অংশগুলো দেখছেন।',
    'getting_started_o2' => 'আপনার পাসওয়ার্ড এখন শুধু আপনি জানেন।',
    'getting_started_o3' => 'যেকোনো পাতা থেকে সাহায্য খুলতে পারেন।',
    'getting_started_t1' => 'ভাষা বদলের বাটনে বাংলা বা English বেছে নিন। আপনার পছন্দ সেভ থাকবে।',
    'getting_started_t2' => 'আটকে গেলে ওপরের কম্পাসে চাপুন। সেখানে এই নির্দেশিকা পাবেন। ট্যুর আবার দেখতে “ড্যাশবোর্ড ট্যুর শুরু করুন” চাপুন।',
    'getting_started_t3' => 'ডিলার ও সাব-ডিলার: “অফিসে যোগাযোগ” খুলে “সাহায্য” থেকে অফিসকে জানান।',
    'getting_started_w1' => 'আপনার কোড বা পাসওয়ার্ড কাউকে দেবেন না। কোনো স্টাফ চাইলেও না।',
    'getting_started_w2' => 'আসল সিস্টেমে পরীক্ষার (ডেমো) তথ্য দেবেন না।',
    'profile_security_s1' => 'প্রোফাইল খুলুন। ডিলার ও সাব-ডিলার মেনু থেকে “আমার প্রোফাইল” খুলুন। সেখানে আপনার নাম, বাবা-মায়ের নাম, জন্ম তারিখ, পরিচয়পত্র (শেষ ৪ সংখ্যা), ঠিকানা ও দায়িত্বের এলাকা দেখবেন। অফিসের লোক ও মালিক ওপরের ছবির মেনু থেকে “আমার প্রোফাইল” খুলুন। সেখানে বাঁ দিকে আপনার ছবি, নাম ও পদ, আর ডান দিকে আলাদা আলাদা বক্স পাবেন: নাম ও যোগাযোগ, ব্যক্তিগত তথ্য, পরিচয়পত্র (এনআইডি), কাজের তথ্য, অ্যাকাউন্ট ও নিরাপত্তা।',
    'profile_security_s2' => 'নাম, দোকানের নাম, ফোন, ইমেইল ও ঠিকানা ঠিক আছে কিনা দেখুন। অফিসের লোক ও মালিক: প্রতিটি বক্স আলাদা করে সংরক্ষণ হয়। ইংরেজিতে নাম লিখলে বাংলা নাম আপনা-আপনি বসে যায়।',
    'profile_security_s3' => 'কিছু ভুল থাকলে “আমার তথ্য ঠিক করুন” বা “তথ্য বদলের অনুরোধ” ব্যবহার করুন। প্রোফাইলে কোম্পানি তালা দিলে শুধু কোম্পানি বদলাতে পারে। অফিসের লোক নিজের ভূমিকা, শাখা ও পদবি এখানে বদলাতে পারেন না; এগুলো মালিক ঠিক করেন। মালিক “পদবি” বক্সে নামের নিচের পদটি লিখতে পারেন।',
    'profile_security_s4' => 'নিজের পরিচয় দেখাতে চাইলে “আইডি কার্ড ডাউনলোড” চাপুন।',
    'profile_security_s5' => 'নিরাপত্তা পাতা খুলুন। ডিলার ও সাব-ডিলার “আমার প্রোফাইল” থেকে “পাসওয়ার্ড ও নিরাপত্তা” খুলুন। অফিসের লোক ছবির মেনু থেকে “অ্যাকাউন্ট নিরাপত্তা” খুলুন।',
    'profile_security_s6' => 'পাসওয়ার্ড বদলাতে “বর্তমান পাসওয়ার্ড” ঘরে এখনকার পাসওয়ার্ড লিখুন। নতুন অ্যাকাউন্ট হলে অফিসের দেওয়া অস্থায়ী পাসওয়ার্ড লিখুন। তারপর নতুন পাসওয়ার্ড দুই ঘরে লিখে “পাসওয়ার্ড আপডেট” চাপুন।',
    'profile_security_s7' => 'নতুন পাসওয়ার্ড কমপক্ষে ৮ অক্ষরের হতে হবে। ১২৩৪৫৬৭৮, ১১১১১১১১, নিজের ফোন নম্বর বা নিজের কোড দেবেন না।',
    'profile_security_s8' => 'নিরাপত্তা পাতায় দেখুন কোন কোন ডিভাইসে আপনি লগইন আছেন। অচেনা কোনোটি থাকলে সেটি লগআউট করুন।',
    'profile_security_s9' => 'স্টাফের জন্য দুই ধাপের লগইন (2FA) চালু থাকলে অথেন্টিকেটর অ্যাপ যুক্ত করুন। রিকভারি কোডগুলো কাগজে লিখে নিরাপদে রাখুন।',
