    'deliveries_dues_s7' => 'মাল কম এলে মাল বিলি করার আগে প্যাকেটের ছবি তুলুন। তারপর অর্ডার নম্বরসহ সাপোর্ট অনুরোধ পাঠান।',
    'deliveries_dues_s8' => 'কিছু মাল পাঠানো বাকি থাকলে অর্ডারে তা লেখা থাকে। বেশি দেরি হলে অফিসকে বলে বাকিটা বাতিল করুন আর টাকা ফেরত নিন।',
    'deliveries_dues_o1' => 'কোন অর্ডার পথে আছে আর কোনটা পুরো হাতে পেয়েছেন, তা জানতে পারবেন।',
    'deliveries_dues_o2' => 'হিসাব বিভাগ পুরো টাকা যাচাই করার পরই মাল পাঠানো হয়।',
    'deliveries_dues_o3' => 'বাতিল আর ফেরত অর্ডারও কারণসহ আপনার অর্ডারের তালিকায় থাকে।',
    'deliveries_dues_t1' => 'যাচাইয়ের অপেক্ষায় থাকা টাকা, যাচাই না হওয়া পর্যন্ত ধরা হয় না।',
    'deliveries_dues_t2' => '“ডেলিভারি হয়েছে” মানে কোম্পানি আপনাকে মাল পৌঁছে দিয়েছে। আপনার নিজের বিক্রির সাথে এর সম্পর্ক নেই।',
    'deliveries_dues_w1' => 'কুরিয়ারের লেবেল বদলাবেন না। কোনো অমিল থাকলে সঙ্গে সঙ্গে জানান।',
    'deliveries_dues_w2' => 'ডেলিভারি ফেরত দিলে অর্ডার নম্বরসহ লিখিত কারণ দিন।',
    'commissions_pool_s1' => 'ডিলার ও সাব-ডিলার: “ওয়ালেট” খুলুন। প্রতিটি কার্ডে এক ধরনের আয়ের মোট টাকা দেখবেন।',
    'commissions_pool_s2' => 'কোনো কার্ডে চাপুন। নিচের তালিকায় শুধু ওই আয় দেখাবে।',
    'commissions_pool_s3' => 'অর্ডার ডেলিভারি হলে কমিশন যোগ হয়। কিছু মাল পৌঁছালে শুধু সেই মালের কমিশন হয়।',
    'commissions_pool_s4' => 'কোনো অর্ডার বাতিল বা ফেরত হলে সেই মালের কমিশনও হিসাব থেকে বাদ যায়।',
    'commissions_pool_s5' => 'অফিস: “ট্রেজারি” → “অর্ডারের হিসাব” খুলুন। একটি অর্ডারে চাপুন। প্রতিটি কমিশনের হার, ধরন আর কে বা কোন ফান্ড পেয়েছে, তা দেখবেন।',
    'commissions_pool_s6' => 'কোনো অর্ডারে স্টাফ কমিশন না দিলে ওই টাকা কোম্পানির ফান্ডে যায়। স্টাফের লেখা কারণও সেখানে থাকে।',
    'commissions_pool_s7' => 'সংক্ষেপে: পুরো টাকা পরিশোধ ও ডেলিভারি হওয়া প্রতিটি কেনা থেকে কোম্পানি রাখে :dealer_company_rate% (ডিলারের কেনা) বা :sub_company_rate% (সাব-ডিলারের কেনা)। বাকিটা কমিশন ফান্ডে যায়। কোম্পানির নিয়মে তা পার্টনারদের মধ্যে ভাগ হয়।',
    'commissions_pool_o1' => 'অর্ডারের প্রতিটি টাকা কার কাছে বা কোন ফান্ডে গেছে, তা বের করা যায়।',
    'commissions_pool_t1' => 'ওয়ালেটের তালিকায় তারিখ বেছে একদিন, এক মাস বা যেকোনো তারিখের হিসাব দেখুন।',
    'commissions_pool_w1' => 'কমিশনের হার অফিস ঠিক করে। পার্টনারকে অন্য কোনো হারের কথা দেবেন না।',
    'withdrawals_s1' => '“ওয়ালেট” খুলে “টাকা তুলুন” চাপুন।',
    'withdrawals_s2' => '“ব্যাংক বা মোবাইলে নিন” বেছে নিন। অথবা “এই টাকায় অর্ডার করুন” বেছে নিন।',
    'withdrawals_s3' => 'টাকার পরিমাণ আর আপনার অ্যাকাউন্ট নম্বর লিখুন। প্রতিটি মাধ্যমে একবারে তোলার একটি সীমা আছে। সীমাটি এই ফর্মেই দেখবেন।',
    'withdrawals_s4' => 'আবেদন পাঠালে টাকাটা আলাদা করে রাখা হয়। অফিস যাচাই না করা পর্যন্ত তা খরচ হয় না। আবেদনটি “ওয়ালেট” পাতায় থাকে, তাই অফিস কী করল তা দেখতে পাবেন।',
    'withdrawals_s5' => 'আবেদন অফিসের অপেক্ষায় থাকলে “অনুরোধ বাতিল করুন” চাপুন। টাকা সঙ্গে সঙ্গে ওয়ালেটে ফিরে আসে। অনুমোদনের পরে আর বাতিল করা যায় না। তখন অফিসে ফোন করুন।',
    'withdrawals_s6' => 'অর্ডার করতে চাইলে অর্ডারের পাতায় “আমার অ্যাকাউন্ট থেকে” বাছা অবস্থায় যাবেন। অর্ডার না দেওয়া পর্যন্ত কোনো টাকা কাটে না।',
    'withdrawals_s7' => 'অফিস: “টাকা তোলার অনুরোধ” খুলে যাচাই করে অনুমোদন দিন। হিসাব বিভাগের একজন স্টাফ অনুমোদন দেন, অন্য একজন টাকা পাঠান। মালিকের ঠিক করা সীমার (শুরুতে ৳১,০০,০০০) সমান বা বেশি হলে শুধু মালিক অনুমোদন করবেন। মালিক একাই অনুমোদন ও পরিশোধ করতে পারেন।',
    'withdrawals_s8' => 'অফিস: যিনি টাকা পাঠান, তিনি রসিদ যোগ করেন। রসিদ তখনই না থাকলে “টাকা পাঠিয়েছি, রসিদ পরে দেব” বেছে নিন। পরে “রসিদ যোগ করুন” চাপুন।',
    'withdrawals_o1' => 'প্রতিটি টাকা তোলা “ওয়ালেট” পাতায় এক লাইনে থাকে। টাকা দেওয়া হলে রসিদও থাকে।',
    'withdrawals_o2' => 'অফিস টাকা পাঠানোর আগে আবেদন বাতিল করলে টাকা ওয়ালেটে ফিরে আসে।',
    'withdrawals_t1' => 'ব্যাংক, বিকাশ, নগদ বা রকেটের নম্বর প্রোফাইলে “আমার টাকা নেওয়ার অ্যাকাউন্ট”-এ রাখুন। টাকা তোলার সময় সেখান থেকে বেছে নেবেন। নম্বর ঠিক রাখুন, নইলে টাকা ফেরত আসতে পারে। অ্যাকাউন্ট বদলালে নিরাপত্তার জন্য কিছুক্ষণ টাকা তোলা বন্ধ থাকে।',
    'withdrawals_t2' => 'আপনার TIN (কর নম্বর) থাকলে টাকা তোলার ফর্মেই লিখে রাখতে পারেন।',
    'withdrawals_w1' => 'ফোন নম্বর বা পাসওয়ার্ড বদলালে কিছুক্ষণ টাকা তোলার আবেদন করা যায় না। সাধারণত ২ ঘণ্টা। অন্য কেউ অ্যাকাউন্টে ঢুকলে এতে আপনার টাকা সুরক্ষিত থাকে।',
    'withdrawals_w2' => 'আপনার অ্যাকাউন্ট বন্ধ (সাসপেন্ড) থাকলে খোলা আবেদনগুলো আটকে থাকে। তখন টাকা পাঠানো হয় না। অ্যাকাউন্ট আবার চালু হলে আবেদন এগোয়।',
    'withdrawals_w3' => 'প্রথমবার টাকা তোলার আগে আপনার NID নম্বর অফিসে জমা থাকতে হয়। না থাকলে প্রোফাইল বা টাকা তোলার পাতা থেকে নম্বর ও কার্ডের ছবি পাঠান; অফিস মিলিয়ে দেখলে টাকা তোলা খুলে যায়।',
    'withdrawals_w4' => '“টাকা তুলুন” বোতাম না দেখলে পাতার নোটিশ পড়ুন। সেখানে কারণ লেখা আছে।',
    'reports_s1' => 'ডিলার ও সাব-ডিলার: ড্যাশবোর্ডের নিচে রিপোর্টের ট্যাব আছে। “মোট রিপোর্ট” চাপলে সব আয় দেখবেন। আলাদা আয়ের ট্যাবে শুধু সেই আয় দেখবেন।',
    'reports_s2' => '“ওয়ালেট” খুলে তালিকার সার্চ, ফিল্টার আর তারিখ ব্যবহার করুন।',
    'reports_s3' => '“ফাইল নামান” থেকে হিসাবের ফাইল, “পুরো রিপোর্ট (পিডিএফ)” আর সনদ নিন।',
    'reports_s4' => 'অফিস: “ট্রেজারি” → “অর্ডারের হিসাব” খুলুন। একটি সারিতে চাপলে ওই অর্ডারের প্রতিটি টাকা কোথায় গেছে, তা দেখবেন।',
    'reports_s5' => 'অফিস: অর্ডারের হিসাবের “ফাইল নামান” থেকে ফাইল নিন। আপনার কাজের অনুমতি অনুযায়ী ফাইলই দেখবেন।',
    'reports_o1' => 'পাতায় আর ফাইলে একই হিসাব থাকে।',
    'reports_t1' => 'টাকার হিসাবে শুধু ডেলিভারি হওয়া মাল ধরা হয়।',
    'reports_w1' => 'ফাইলে নাম আর টাকার হিসাব থাকে। এগুলো অফিসের বাইরে দেবেন না।',
    'money_rules_s1' => 'শুধু পুরো টাকা পরিশোধ হওয়া আর ডেলিভারি হওয়া কেনা গোনা হয়।',
    'money_rules_s2' => 'নিজের কেনার আয়: যিনি কেনেন, তিনি নিজের কেনার :cashback_rate% ফেরত পান।',
    'money_rules_s3' => 'রেফারেল আয় (সরাসরি) আর D2D আয়: যিনি ক্রেতাকে এনেছেন, তিনি পান :referral_rate%। তার ওপরের দুজন পান :gen2_rate% (২য় প্রজন্ম) আর :gen3_rate% (৩য় প্রজন্ম)। ওপরে কেউ না থাকলে ওই ভাগ কোম্পানির লাভে যায়।',
    'money_rules_s4' => 'এরিয়া ডিলার আয়: :area_rate% ক্রেতার প্লেস কোডের এরিয়া ডিলারদের মধ্যে ভাগ হয়। ম্যানেজমেন্ট :area_management%, বিভাগ :area_division%, জেলা :area_district%, উপজেলা :area_upazila%, ইউনিয়ন বা পৌরসভা :area_union%। কোনো জায়গায় এরিয়া ডিলার না থাকলে ওই ভাগ কোম্পানির লাভে যায়।',
    'money_rules_s5' => 'মাসিক বেতন (ডিলার): :dealer_salary_rate% ক্রেতার বিভাগের বেতন ফান্ডে যায়। ওই মাসে যে ডিলাররা অন্তত :dealer_salary_min কিনেছেন, তারা সমান ভাগে পান।',
    'money_rules_s6' => 'র‍্যাঙ্ক রয়্যালটি: :royalty_rate% প্রতি মাসে ভাগ হয়। ভাগ পান যেসব ডিলার নিজের র‍্যাঙ্ক ধরে রেখেছেন। শুধু সর্বশেষ র‍্যাঙ্কের রয়্যালটি পাবেন।',
    'money_rules_s7' => 'র‍্যাঙ্ক আয় ও র‍্যাঙ্ক ইনসেন্টিভ: :incentive_rate% দিয়ে ইনসেন্টিভের ফান্ড জমে। র‍্যাঙ্কে পৌঁছালেই একবারের “র‍্যাঙ্ক আয়” (MO, AM, SM, ME) দেওয়া হয়। একই মাসে MO আর AM হলে দুটোই পাবেন।',
    'money_rules_s8' => 'মার্কেটিং (:marketing_rate%) আর বাইক ও কার ইনসেন্টিভের ফান্ড (:vehicle_rate%) কোম্পানির ফান্ড। এগুলো প্রচার আর বড় ইনসেন্টিভের জন্য।',
    'money_rules_s9' => 'প্রতিটি মাস আলাদাভাবে বন্ধ হয়। কোনো টার্গেট (বেতন, এরিয়া কমিশন, রয়্যালটি ইত্যাদি) পূরণ না হলে সেই মাসের টাকা কোম্পানির লাভে যায়। কারণও লেখা থাকে। এই টাকা পরের মাসে যায় না।',
    'money_rules_s10' => 'শুধু তিনটি ফান্ড মাসের পর মাস জমে: র‍্যাঙ্ক পুরস্কারের ফান্ড, সাব-ডিলারের ট্যুর ফান্ড আর বাইক ও গাড়ির ফান্ড।',
    'money_rules_s11' => 'আপনার অ্যাকাউন্ট বন্ধ (সাসপেন্ড) থাকলে আপনার কমিশন আটকে থাকে। “ওয়ালেট” পাতার “আপনার জন্য আটকে থাকা কমিশন” অংশে তা দেখবেন। অ্যাকাউন্ট আবার চালু হলে টাকা নিজে থেকে আপনার কাছে আসে। অ্যাকাউন্ট বন্ধ করে দিলে ৩ মাসের বেশি আটকে থাকা কমিশন কোম্পানির লাভে যায়।',
    'money_rules_o1' => 'কোন টাকা সাথে সাথে আসে আর কোনটা মাস শেষের অপেক্ষায় থাকে, আপনি বুঝতে পারেন।',
    'money_rules_o2' => 'আপনি জানেন, টার্গেট মিস হলে সেই মাসের ভাগ চলে যায়। তা পরের জন্য জমা থাকে না।',
    'money_rules_t1' => 'প্রতিটি মাসিক টার্গেটে কতটা কাছে আছেন দেখতে ড্যাশবোর্ডে “আমার অগ্রগতি দেখুন” চাপুন।',
    'money_rules_t2' => 'মালিক কোনো হার বদলালে এই পাতায় নতুন হার দেখাবে।',
    'money_rules_w1' => 'মিস হওয়া টার্গেট পরের মাসে পূরণ করবেন ভেবে বসে থাকবেন না। প্রতিটি মাস আলাদা গোনা হয়।',
    'my_money_tabs_s1' => 'ওপরে দেখবেন: এখন কত ব্যবহার করতে পারবেন, কত অপেক্ষায় আছে, আর কত তোলার আবেদনে আছে।',
    'my_money_tabs_s2' => 'কোনো আয়ের কার্ডে চাপুন, যেমন “রেফারেল আয় (সরাসরি)”। নিচের তালিকায় শুধু ওই আয় দেখাবে। টাকা না আসা খাতগুলোও দেখতে “আমার অ্যাকাউন্ট” খুলুন।',
    'my_money_tabs_s3' => 'তালিকায় সার্চ, ফিল্টার আর তারিখ ব্যবহার করুন।',
    'my_money_tabs_s4' => 'আটকে থাকা কমিশন থাকলে “আপনার জন্য আটকে থাকা কমিশন” অংশে দেখবেন। এই টাকা এখনো আপনার ব্যালেন্সে আসেনি।',
    'my_money_tabs_s5' => 'টাকা নিতে বা সেই টাকায় অর্ডার করতে “টাকা তুলুন” চাপুন। ফাইল নিতে “ফাইল নামান” চাপুন।',
    'my_money_tabs_o1' => 'এক পাতা থেকেই টাকা দেখা, তোলা আর মেলানো যায়।',
    'my_money_tabs_t1' => 'একই আয়ের তালিকা আপনার ড্যাশবোর্ডেও আছে। সব খাত, টাকা না এলে ৳০.০০ সহ, দেখতে মেনুর “আমার অ্যাকাউন্ট” খুলুন।',
    'my_money_tabs_w1' => '“টাকা তুলুন” না দেখলে পাতার নোটিশ পড়ুন। সেখানে কারণ লেখা আছে।',
    'rewards_milestones_s1' => 'পার্টনার: ড্যাশবোর্ডে “আমার অগ্রগতি দেখুন” চাপুন। প্রতিটি টার্গেট সেখানে দেখবেন। এখন টিমের বিক্রি লাগবে: বাইকের জন্য :bike_target, গাড়ির জন্য :car_target।',
    'rewards_milestones_s2' => 'শুরু থেকে আপনার পুরো টিমের শুধু পুরো টাকা পরিশোধ ও ডেলিভারি হওয়া অর্ডার গোনা হয়। প্রতিটি সরাসরি লাইন থেকে একটি সীমা পর্যন্ত গোনা হয়: বাইকের জন্য :bike_cap, গাড়ির জন্য :car_cap।',
    'rewards_milestones_s3' => 'বাইকের ফান্ড আর গাড়ির ফান্ড আলাদা। পুরস্কার নিজের ফান্ড থেকেই দেওয়া হয়। মাস শেষে এই ফান্ড হারায় না। এক মাস থেকে পরের মাসে জমতে থাকে।',
    'rewards_milestones_s4' => 'স্টাফ: “ট্রেজারি” → “খরচ, বাজেট ও বাকি কাজ” → “পুরস্কার” খুলে পুরস্কার দিন। মাধ্যম আর রেফারেন্স লিখুন, তাহলে রসিদ তৈরি হবে।',
    'rewards_milestones_s5' => 'সাপোর্টে জিজ্ঞেস করার আগে অগ্রগতির বার আর যোগ্য বিক্রি দেখে নিন।',
    'rewards_milestones_s6' => 'মালিক: বাইক ও গাড়ির পুরস্কারের টাকা ঠিক করে রাখুন। না থাকলে পুরস্কার অনুমোদন হয় না। পুরস্কারের পাওনা টাকা দৈনন্দিন খরচের নগদ থেকে আলাদা রাখুন।',
    'rewards_milestones_o1' => 'অগ্রগতিতে শুধু যোগ্য বিক্রি ধরা হয়।',
    'rewards_milestones_o2' => 'পুরস্কারের পেমেন্ট “মাস শেষ: কমিশন ও বেতন দিন” পাতায় লেখা থাকে।',
    'rewards_milestones_t1' => 'পুরস্কার পাওয়ার কাগজ আর সার্কুলারের ছবি তুলে নিজের কাছে রাখুন।',
    'rewards_milestones_t2' => 'পুরস্কারের জিনিস আর আপনার তোলার মতো টাকা আলাদা।',
    'rewards_milestones_w1' => 'শেষ না হওয়া টার্গেটকে নিশ্চিত পাওনা বলে কাউকে কথা দেবেন না।',
    'subdealer_salary_tour_s1' => 'ড্যাশবোর্ডে “আমার অগ্রগতি দেখুন” চাপুন। কত বেতন জমেছে অথচ এখনো আসেনি, তা দেখবেন।',
    'subdealer_salary_tour_s2' => '“ওয়ালেট” খুলে তালিকার ফিল্টারে “মাসিক বেতন” বেছে নিন। বেতনের টাকার লাইনগুলো দেখবেন।',
    'subdealer_salary_tour_s3' => 'পুরো টাকা পরিশোধ ও ডেলিভারি হওয়া প্রতিটি কেনা বেতনে গোনা হয়। কোনো ন্যূনতম পরিমাণ নেই।',
    'subdealer_salary_tour_s4' => '“মাস শেষ: কমিশন ও বেতন দিন” চালানোর পর টাকা ওয়ালেটে এসেছে কি না দেখুন।',
    'subdealer_salary_tour_s5' => 'ট্যুর ফান্ড আলাদা জমে। এটি আপনার তোলার টাকার সাথে মেশে না। মাস বন্ধ হলেও এটি শূন্য হয় না।',
    'subdealer_salary_tour_s6' => 'ডিলার (যাঁর সাব-ডিলার আছে): তাদের বিক্রির পরিকল্পনায় সাহায্য করুন। ভবিষ্যতের বেতনের ভরসায় নিজের টাকা ধার দেবেন না।',
    'subdealer_salary_tour_s7' => 'স্টাফ: “ট্রেজারি” → “খরচ, বাজেট ও বাকি কাজ” → “মাসের হিসাব” থেকে মাস শেষের বেতন চালান। বেতনের প্রতিটি লাইন কোন অর্ডার থেকে এসেছে, তা মিলিয়ে নিন।',
    'subdealer_salary_tour_s8' => 'বেতন হিসাবে উঠেছে, কিন্তু আপনার ডেলিভারি হওয়া বিক্রির সাথে মিলছে না? সাপোর্ট অনুরোধ পাঠান।',
    'subdealer_salary_tour_o1' => 'এই মাসে কত বেতন জমেছে অথচ এখনো আসেনি, তা দেখতে পারবেন।',
    'subdealer_salary_tour_o2' => 'দেওয়া টাকা “মাস শেষ: কমিশন ও বেতন দিন” পাতার সাথে মেলে।',
    'subdealer_salary_tour_o3' => 'ট্যুর ফান্ড আর তোলার মতো টাকা আলাদা থাকে।',
    'subdealer_salary_tour_t1' => 'ইনভয়েসগুলো রেখে দিন। পুরো টাকা পরিশোধ ও ডেলিভারি হওয়া প্রতিটি অর্ডারে সেই মাসের বেতন বাড়ে।',
    'subdealer_salary_tour_t2' => 'বেতনের সাময়িক অফার বা বদলের জন্য সার্কুলারে নজর রাখুন।',
    'subdealer_salary_tour_w1' => 'ট্যুর ফান্ড তোলার টাকা নয়। অফিস এই টাকায় আপনাকে কোম্পানির ট্যুরে পাঠায়।',
    'subdealer_salary_tour_w2' => 'স্টাফ “কমিশনের নিয়ম ও হার” পাতার বাইরে বেতনের শতাংশ বদলাবেন না।',
    'network_genealogy_s1' => 'মেনু থেকে “আমার টিম ও গ্রাহক” খুলুন।',
    'network_genealogy_s2' => 'আপনার কোড কপি করুন, অথবা QR কোড শেয়ার করুন।',
    'network_genealogy_s3' => 'আগ্রহী মানুষকে আপনার কোডসহ ওয়েবসাইটের যোগদানের ফর্মে পাঠান।',
    'network_genealogy_s4' => 'আপনার টিমে কে আছেন আর কে সক্রিয়, তা দেখুন।',
