    'network_genealogy_s6' => 'তালিকা নিজের কাছে রাখতে “টিমের তালিকা ডাউনলোড (এক্সেলে খোলে)” চাপুন।',
    'network_genealogy_s7' => 'স্টাফ ও মালিক: অফিসে “কে কার অধীনে” পাতা খুলে পুরো টিম দেখুন।',
    'network_genealogy_s8' => 'স্টাফ ও মালিক: নতুন সদস্য ঠিক রেফারকারীর নিচে এসেছেন কিনা মিলিয়ে নিন।',
    'network_genealogy_o1' => 'নতুন ডিলার আপনার কোড দিয়ে আপনার টিমে যোগ হন।',
    'network_genealogy_o2' => 'আপনার টিমের সবাইকে এক জায়গায় দেখতে পান।',
    'network_genealogy_o3' => 'ডাউনলোড করা তালিকা দেখে টিমকে সহজে সাহায্য করতে পারেন।',
    'network_genealogy_t1' => 'প্রতিটি প্রচারে একই কোড ব্যবহার করুন, তাহলে হিসাব গুলিয়ে যাবে না।',
    'network_genealogy_t2' => 'টাকা পুরো পেয়ে অর্ডার ডেলিভারি হলে তবেই রেফার কমিশন হয়। সরাসরি রেফারকারী পান :referral_rate%, তার উপরের জন :gen2_rate%, আর তার উপরের জন :gen3_rate%। কোনো ধাপে রেফারকারী না থাকলে সেই অংশ কোম্পানির লাভের ফান্ডে যায়।',
    'network_genealogy_t3' => 'এরিয়া ডিলারের আয় এলাকার ওপর নির্ভর করে। রেফার টিমের সাথে এর কোনো মিল নেই।',
    'network_genealogy_w1' => 'অন্য কারও পাসওয়ার্ড কখনো চাইবেন না বা নিজের কাছে রাখবেন না।',
    'network_genealogy_w2' => 'একজন মানুষের নামে একাধিক অ্যাকাউন্ট সন্দেহ হলে সাপোর্টকে জানান। সাথে প্রমাণ দিন।',
    'ranks_royalties_s1' => 'মেনু থেকে “র‍্যাঙ্ক” খুলুন। অথবা ড্যাশবোর্ডে “আমার অগ্রগতি দেখুন” চাপুন।',
    'ranks_royalties_s2' => 'দেখুন আপনি এখন কোন র‍্যাঙ্কে আছেন আর পরেরটির জন্য কী বাকি।',
    'ranks_royalties_s3' => 'র‍্যাঙ্কের ক্রম: MO (মার্কেটিং অফিসার), AM (এরিয়া ম্যানেজার), SM (সেলস ম্যানেজার), ME (মার্কেটিং এক্সিকিউটিভ)।',
    'ranks_royalties_s4' => 'MO হতে আপনার নিজের কেনা গোনা হয়। AM, SM ও ME হতে টিমের সক্রিয় ডিলার গোনা হয়। নিচের টিপসে সংখ্যা দেখুন।',
    'ranks_royalties_s5' => 'র‍্যাঙ্কে পৌঁছালেই একবারের পুরস্কার পাবেন। একই মাসে MO ও AM হলে দুটোই পাবেন।',
