    'ranks_royalties_w2' => 'স্টাফ হাতে করে কাউকে র‍্যাঙ্ক দেবেন না। এতে হিসাব গুলিয়ে যায়।',
    'prescription_templates_followups_s1' => 'কোনো প্রেসক্রিপশনের নিচে “টেমপ্লেট হিসেবে রাখুন” চেপে একটি নাম দিন।',
    'prescription_templates_followups_s2' => '“নতুন প্রেসক্রিপশন” অংশে “টেমপ্লেট থেকে শুরু করুন” খুলে একটি বেছে নিন। ওষুধ ও পরামর্শ নিজে নিজে বসে যাবে।',
    'prescription_templates_followups_s3' => 'আপনার সব টেমপ্লেট দেখতে বা মুছতে “টেমপ্লেট” ট্যাব খুলুন।',
    'prescription_templates_followups_s4' => 'খাবারের তালিকাও রাখা যায়। কোন রোগে কী খাবেন আর কী খাবেন না, “খাবারের টেমপ্লেট” অংশে একবার লিখে রাখুন।',
    'prescription_templates_followups_s5' => 'প্রেসক্রিপশন লেখার সময় “আবার দেখানোর তারিখ” দিন।',
