    'prescription_templates_followups_s7' => 'রোগী দেখা হয়ে গেলে “দেখা হয়ে গেছে” চাপুন। তিনি তালিকা থেকে সরে যাবেন।',
    'prescription_templates_followups_o1' => 'রোগীর আসার সময় হলে আপনি নোটিশ পাবেন।',
    'prescription_templates_followups_t1' => 'আপনার টেমপ্লেট শুধু আপনি দেখতে পান।',
    'prescription_templates_followups_w1' => 'টেমপ্লেট বেছে নিলে এখন যা লেখা আছে তা বদলে যায়। তাই আগে টেমপ্লেট বেছে নিন, তারপর লিখুন।',
    'staff_people_accounts_s1' => '“নতুন পার্টনারের আবেদন” মেনু খুলুন। “ডিলার আবেদন” বা “সাব-ডিলার আবেদন” বেছে নিন।',
    'staff_people_accounts_s2' => 'একটি আবেদন খুলুন। “অনুমোদনের আগে দেখে নিন” অংশের সতর্কতাগুলো পড়ুন।',
