    'staff_people_accounts_w1' => 'ছবি ও পরিচয়পত্রের কপি অনলাইনে নেওয়া হয় না। মূল কাগজ দেখে নিয়ে তারপর অনুমোদন দিন।',
    'staff_people_accounts_w2' => 'একটি স্টাফ লগইন কয়েকজনে ভাগ করে ব্যবহার করবেন না।',
    'staff_people_accounts_w3' => 'প্রথম পাসওয়ার্ড একবারই দেখানো হয়। না লিখে পাতা বন্ধ করবেন না।',
    'staff_fulfillment_s1' => '“অর্ডারের টাকা যাচাই” মেনু খুলুন। যে পেমেন্ট দেখবেন তার সারি চাপুন।',
    'staff_fulfillment_s2' => 'টাকা সত্যিই এসেছে কি না দেখুন। পরিমাণ, মাধ্যম আর স্ক্রিনশট কোম্পানির অ্যাকাউন্টের সাথে মিলিয়ে নিন।',
    'staff_fulfillment_s3' => 'টাকা এসে থাকলে “পেমেন্ট নিশ্চিত করুন” চাপুন। না এলে “নামঞ্জুর করুন” চাপুন আর কারণ লিখুন।',
    'staff_fulfillment_s4' => '“অর্ডার” মেনুতে অর্ডারটি খুলুন। “এই অর্ডার যাচাই করুন” অংশে পণ্য, দাম আর “এখন পাঠানো যায়” সংখ্যা দেখুন।',
    'staff_fulfillment_s5' => 'পুরো টাকা যাচাই হয়ে থাকলে “সিদ্ধান্ত” ঘরে “অনুমোদিত” বেছে নিন। তারপর “সিদ্ধান্ত সেভ করুন” চাপুন।',
    'staff_fulfillment_s6' => '“কোন শাখা থেকে পাঠাবেন” ঘরে শাখা বেছে নিন। যে পণ্য পরে পাঠাবেন, তার ঘরে ০ লিখুন।',
    'staff_fulfillment_s7' => 'কুরিয়ার বেছে নিন, অথবা কুরিয়ারের নাম ও ট্র্যাকিং নম্বর লিখুন। তারপর “পাঠানোর তথ্য সেভ করুন” চাপুন।',
    'staff_fulfillment_s8' => 'মাল সত্যিই পৌঁছালে “ডেলিভারি নিশ্চিত করুন” চাপুন।',
    'staff_fulfillment_s9' => 'পার্টনার বাতিল বা ফেরত চাইলে অর্ডারের “বাতিল, ফেরত ও টাকা ফেরত” অংশ খুলুন। ঠিক মনে হলে “অনুমোদন দিন” চাপুন। নইলে “নামঞ্জুর করুন” চাপুন।',
    'staff_fulfillment_s10' => 'টাকা ফেরত হলে আরেকজন স্টাফকে অর্ডার খুলে “দেখে নিশ্চিত করছি” চাপতে হয়। ফেরতের টাকা মালিকের ঠিক করা সীমার (শুরুতে ৳৫০,০০০) সমান বা বেশি হলে দুজনের একজন মালিক হতে হবে। শুধু মালিক (সুপার অ্যাডমিন) একাই শেষ করতে পারেন।',
    'staff_fulfillment_o1' => 'অনুমোদিত অর্ডারের মাল পাঠানো যায়। ডেলিভারি শেষ হলে অর্ডার শেষ হয়।',
    'staff_fulfillment_o2' => 'যে শাখা থেকে মাল যায়, স্টক সেই শাখা থেকেই কমে।',
    'staff_fulfillment_o3' => 'বাতিল বা ফেরত হলে পণ্য স্টকে ফেরে। টাকা আর কমিশনের হিসাবও ঠিক হয়ে যায়।',
    'staff_fulfillment_t1' => 'প্রতিদিন শেষে “ট্রেজারি” → “অর্ডারের হিসাব” দেখুন। পাঠানো মালের সাথে টাকা মিলিয়ে নিন।',
    'staff_fulfillment_t2' => 'না করার সময় কারণ ভদ্রভাবে লিখুন। পার্টনার তা দেখেন। এরপর কী করতে হবে, তাও বলে দিন।',
    'staff_fulfillment_t3' => 'কিছু পণ্য পাঠানো বাকি থাকলে অর্ডারে “কিছু পণ্য এখনো পাঠানো বাকি” বাক্স আসে। ৭ দিন পরে সতর্কতা আসে। দেরি বেশি হলে “বাকিটা বন্ধ করে টাকা ফেরত” বেছে নিতে পারেন।',
