    'inventory_branches_s2' => 'মাল এলে “স্টক যোগ” চাপুন। কত এসেছে লিখুন, আর কারণ বেছে নিন।',
    'inventory_branches_s3' => 'মাল গেলে বা নষ্ট হলে “স্টক বের” চাপুন। কারণ বেছে নিন, যেমন “নষ্ট পণ্য”। হিসাবের ভুল ঠিক করতে কারণ হিসেবে “সংশোধন” বেছে নিন।',
    'inventory_branches_s4' => 'কোনো পণ্যের অর্ডার নেওয়া কিছুদিন বন্ধ রাখতে পণ্যের পাশে “অর্ডার বন্ধ করুন” চাপুন। আবার চালাতে “অর্ডার চালু করুন” চাপুন।',
    'inventory_branches_s5' => 'মাল এক ব্রাঞ্চ থেকে অন্য ব্রাঞ্চে পাঠাতে পণ্যের পাশে “অন্য শাখায় পাঠান” চাপুন। বাকি কাজ “ব্যাচ ও মেয়াদ” পাতার “ব্রাঞ্চ ট্রান্সফার” ট্যাবে হয়।',
    'inventory_branches_s6' => 'নতুন ব্রাঞ্চ খুলতে “ব্রাঞ্চ” পাতায় “ব্রাঞ্চ যোগ” চাপুন। কোড, নাম ও ঠিকানা লিখুন।',
    'inventory_branches_s7' => 'ব্রাঞ্চে স্টাফ দিতে “স্টাফ যুক্ত করুন” চাপুন। কাজ বেছে নিন: ম্যানেজার, স্টোরকিপার বা মাল পাঠানোর দায়িত্ব।',
    'inventory_branches_s8' => 'অর্ডার পাঠানোর সময় কোন ব্রাঞ্চ থেকে মাল যাবে, তা বেছে নিন।',
    'inventory_branches_o1' => 'পণ্যের তালিকায় যা দেখায়, গুদামে আসলে তাই থাকে।',
    'inventory_branches_o2' => 'প্রতিটি চালু ব্রাঞ্চের একজন দায়িত্বপ্রাপ্ত স্টাফ থাকেন।',
    'inventory_branches_o3' => 'পাঠানো প্রতিটি অর্ডারে লেখা থাকে, কোন ব্রাঞ্চ থেকে মাল গেছে।',
    'inventory_branches_o4' => 'ডেলিভারির জন্য বের হওয়া মাল “কুরিয়ারে আছে” দেখায়। সেই মাল স্টকে ধরা হয় না। ফেরত এলে আবার স্টকে যোগ হয়।',
    'inventory_branches_t1' => 'একসাথে অনেক পণ্যের স্টক বদলানোর আগে অর্ডার নেওয়া বন্ধ রাখুন।',
    'inventory_branches_t2' => 'ব্রাঞ্চের কোড বদলাবেন না। রিপোর্টে এই কোড দেখায়।',
    'inventory_branches_t3' => 'নতুন ব্রাঞ্চ চালুর সময় শুরুর স্টক লিখে রাখুন।',
    'inventory_branches_t4' => 'সব পণ্যের তালিকা পিডিএফে পেতে “স্টক প্রিন্ট” চাপুন। এখন পণ্যের ছবি আগের চেয়ে বড় দেখায়।',
    'inventory_branches_w1' => 'যে ব্রাঞ্চে স্টক বা পুরোনো অর্ডার আছে, সেটি মুছতে পারবেন না। দরকার হলে ব্রাঞ্চটি বন্ধ করে রাখুন।',
    'inventory_branches_w2' => 'একই পণ্যের স্টক একসাথে দুই জায়গা থেকে বদলাবেন না। হিসাব গোলমাল হবে।',
    'inventory_branches_w3' => 'একবারে ১০,০০,০০০ ইউনিটের বেশি লেখা যায় না। সংখ্যা ভুল হলে সিস্টেম আটকে দেয়।',
    'branch_performance_s1' => '“রিপোর্ট” মেনু থেকে “ব্রাঞ্চের বিক্রি” খুলুন।',
    'branch_performance_s2' => 'সময় বেছে নিন: “আজ”, “এই মাস” বা “তারিখ বেছে নিন”।',
    'branch_performance_s3' => 'নিজের তারিখ দিলে “দেখুন” চাপুন।',
    'branch_performance_s4' => 'একটি ব্রাঞ্চ বেছে নিন, অথবা “সব ব্রাঞ্চ” রাখুন।',
    'branch_performance_s5' => 'ওপরের মোট হিসাব দেখুন: অর্ডার, ডেলিভারি হওয়া অর্ডারের মূল্য, আদায় করা টাকা, পরিশোধ বাকি ও আনুমানিক লাভ।',
    'branch_performance_s6' => 'কোন অর্ডারে কত হলো, তা নিচের তালিকায় দেখুন। খুঁজতে অর্ডার নম্বর, নাম বা কোড লিখুন।',
    'branch_performance_s7' => 'সব অর্ডার এক্সেল ফাইলে চাইলে “ডাউনলোড (এক্সেল)” চাপুন। রিপোর্টের অনুমতি থাকলেই এই বোতাম দেখা যায়।',
    'branch_performance_o1' => 'একই সময়ের হিসাবে ব্রাঞ্চগুলোর তুলনা করা যায়।',
    'branch_performance_o2' => 'যে অর্ডারের ব্রাঞ্চ ঠিক করা হয়নি, সেটি “ঠিক করা হয়নি” নামে আলাদা দেখায়।',
    'branch_performance_o3' => 'কোনো পণ্যের কেনার খরচ লেখা না থাকলে তার লাভ শূন্য দেখাতে পারে। তাই ভুলটা চোখে পড়ে।',
    'branch_performance_t1' => 'লাভ = (বিক্রির দাম − কেনার খরচ) × পরিমাণ। তাই প্রতিটি পণ্যে “কেনার খরচ” ঠিক রাখুন।',
    'branch_performance_t2' => 'দিনের হিসাব কোম্পানির সময় ধরে হয়। তারিখ বাছার সময় এটা মনে রাখুন।',
    'branch_performance_t3' => 'ব্রাঞ্চের স্টাফরা শুধু নিজের ব্রাঞ্চের হিসাব দেখতে পান।',
    'branch_performance_w1' => 'আনুমানিক লাভকে পাকা হিসাব মনে করবেন না। এটা অডিট করা লাভ-ক্ষতির হিসাব নয়।',
    'branch_performance_w2' => 'অর্ডারের দাম, টাকা ও লাভে শুধু ডেলিভারি হওয়া মাল ধরা হয়। পাঠানো কিন্তু এখনো না পৌঁছানো মাল এতে আসে না।',
    'product_facts_s1' => '“পণ্য ও স্টক” মেনু থেকে “পণ্য” খুলুন। পণ্যটি বেছে এডিট করুন।',
    'product_facts_s2' => 'তারকা চিহ্ন দেওয়া ঘর অবশ্যই ভরুন। “ঐচ্ছিক” লেখা ঘর খালি রাখা যায়।',
    'product_facts_s3' => '“ওয়েবসাইটের জন্য পণ্যের তথ্য” অংশে লিখুন: প্রস্তুতকারক, নিবন্ধন নম্বর, কার্যকারিতা, উপাদান, ব্যবহার বিধি (মাত্রা ও খাওয়ার নিয়ম), সতর্কতা ও সংরক্ষণের নিয়ম।',
    'product_facts_s4' => 'বাংলা ও ইংরেজি ঘর পাশাপাশি আছে। ইংরেজিতে লিখলে বাংলা ঘর নিজে ভরে যেতে পারে। বাংলাটা পড়ে ঠিক করে নিন।',
    'product_facts_s5' => '“স্বাস্থ্য বিষয়ের ট্যাগ” অংশে পণ্যের সাথে মেলে এমন ট্যাগে টিক দিন। নতুন ট্যাগ লাগলে “ট্যাগ যোগ করুন” চাপুন।',
    'product_facts_s6' => 'পণ্যের নামের নিচে “প্যাক সাইজ” ঘরে সাইজ লিখুন, যেমন “১০০ মিলি”। পরেও যেকোনো সময় বদলানো যায়।',
    'product_facts_s7' => 'একই পণ্যের অন্য সাইজ থাকলে “এই পণ্যের অন্য সাইজ” অংশে “সাইজ বদলান” চাপুন।',
    'product_facts_s8' => 'শেষে “পণ্য সেভ করুন” চাপুন।',
    'product_facts_o1' => 'ওয়েবসাইটের পণ্যের পাতায় শুধু আপনার লেখা তথ্য দেখা যায়।',
    'product_facts_o2' => 'যে ঘর খালি রাখবেন, তার নাম বা শিরোনামও ওয়েবসাইটে দেখা যায় না।',
    'product_facts_t1' => 'নিবন্ধন নম্বর সনদ দেখে হুবহু লিখুন। সনদ না থাকলে ঘর খালি রাখুন।',
    'product_facts_t2' => 'প্রস্তুতকারক, গ্রুপ, কার্যকারিতা, ব্যবহার বিধি ও মেয়াদের তারিখ না দিলেও পণ্য সেভ হয়।',
    'product_facts_w1' => 'ট্যাগে শুধু বিষয়ের নাম লিখুন, যেমন “হজম”। রোগ সারে বা চিকিৎসা হয়, এমন কথা লিখবেন না। এমন কথা থাকলে সিস্টেম ট্যাগ নেয় না।',
    'product_facts_w2' => 'যা সত্য এবং যার প্রমাণ দেখাতে পারবেন, শুধু তাই লিখুন।',
    'product_reviews_s1' => 'নতুন মতামত এলে আপনি নোটিশ পাবেন।',
    'product_reviews_s2' => '“ওয়েবসাইট” মেনু থেকে “গ্রাহকের মতামত” খুলুন।',
    'product_reviews_s3' => 'যে মতামত “অপেক্ষায়” আছে, সেটি পড়ুন।',
    'product_reviews_s4' => '“অবস্থা বদলান” চাপুন। “অনুমোদিত” বা “নামঞ্জুর” বেছে নিয়ে সেভ করুন।',
    'product_reviews_o1' => 'যে মতামত অনুমোদন করবেন, শুধু সেটিই ওয়েবসাইটে দেখা যায়।',
    'product_reviews_t1' => 'প্রতিদিন একবার “অপেক্ষায়” থাকা মতামত দেখুন, যাতে জমে না থাকে।',
    'product_reviews_w1' => 'যে মতামতে লেখা আছে পণ্যে রোগ সেরেছে বা চিকিৎসা হয়েছে, সেটি “নামঞ্জুর” করুন।',
    'stock_batches_s1' => 'স্টক যোগ করার সময় বা ক্রয়ের মাল নেওয়ার সময় ব্যাচ নম্বর লিখুন।',
    'stock_batches_s2' => 'মেয়াদের তারিখ জানা থাকলে লিখুন। না দিলেও চলবে।',
    'stock_batches_s3' => '“পণ্য ও স্টক” মেনু থেকে “ব্যাচ ও মেয়াদ” খুলুন।',
    'stock_batches_s4' => '“মেয়াদ শেষের পথে” ট্যাবে ৩০, ৬০ বা ৯০ দিন বেছে নিন। সেই সময়ের মধ্যে কোন মালের মেয়াদ শেষ হবে, তা দেখা যাবে।',
    'stock_batches_s5' => 'কত দিন আগে সতর্কতা চান, তা “মেয়াদ শেষের কত দিন আগে জানাবে” থেকে বেছে “সেভ করুন” চাপুন।',
    'stock_batches_s6' => 'মেয়াদ শেষ হওয়া মাল আলাদা তালিকায় দেখা যায়। সেগুলো আর পাঠানো যায় না।',
    'stock_batches_s7' => 'মেয়াদ শেষ মাল সরাতে “স্টক বের” চাপুন। কারণ হিসেবে “মেয়াদ শেষ স্টক” বেছে নিন।',
    'stock_batches_s8' => '“তথ্য বাকি” ট্যাবে দেখুন কোন ব্যাচের নম্বর লেখা নেই। প্যাকেট দেখে নম্বর লিখে “তথ্য লিখুন” চাপুন।',
    'stock_batches_o1' => 'কোনো ব্যাচের মেয়াদ শেষের কাছে এলে বা শেষ হলে স্টকের স্টাফরা নোটিশ পান।',
    'stock_batches_o2' => 'ব্যাচ নম্বর না লিখলেও মাল ঢোকে। সেই মাল “তথ্য বাকি” ট্যাবে থাকে, পরে লেখা যায়।',
    'stock_batches_t1' => 'ক্রেতারা ওয়েবসাইটের “ব্যাচ নম্বর যাচাই করুন” পাতায় প্যাকের ব্যাচ নম্বর মিলিয়ে নিতে পারেন।',
    'stock_batches_w1' => 'কোনো ব্রাঞ্চে শুধু মেয়াদ শেষ মাল থাকলে সেগুলো পাঠানো যাবে না।',
    'stock_batches_w2' => 'মেয়াদের তারিখ না দিলে ওই মালের মেয়াদ শেষের সতর্কতা আসবে না।',
    'purchasing_goods_s1' => '“সাপ্লায়ার” ট্যাবে “সাপ্লায়ার যোগ করুন” চাপুন। নাম ও যোগাযোগ লিখুন।',
    'purchasing_goods_s2' => '“ক্রয় অর্ডার” ট্যাবে “নতুন ক্রয় অর্ডার” চাপুন। সাপ্লায়ার, যে ব্রাঞ্চে মাল আসবে, পণ্য ও পরিমাণ দিন। তারপর “খসড়া হিসেবে রাখুন” চাপুন।',
    'purchasing_goods_s3' => 'সাপ্লায়ারকে অর্ডার জানানো হলে “সাপ্লায়ারকে পাঠানো হয়েছে” চাপুন।',
