    'trust_pages_o1' => 'আপনি যা পূরণ করে চালু করেছেন, দর্শকরা শুধু সেটুকুই দেখেন।',
    'trust_pages_o2' => 'ওয়েবসাইট থেকে অভিযোগ এলে একটি “ট্র্যাকিং নম্বর” হয়। আপনি নোটিশ পান।',
    'trust_pages_t1' => 'খসড়া লেখার ওপর ভরসা করার আগে প্রতিটি লেখা পড়ে নিন।',
    'trust_pages_t2' => 'পার্টনারশিপ ছাড়ার পাতা আপনি ও আপনার আইনজীবী লিখবেন। এর কোনো খসড়া নেই। লেখা না দেওয়া পর্যন্ত পাতাটি লুকানো থাকে।',
