    'sales_kit_schemes_owner_s3' => 'ফাইলের তথ্য বা ফাইল বদলাতে “এডিট” চাপুন। কারণ লিখুন। ফাইল সরাতে “বাদ দিন” চাপুন।',
    'sales_kit_schemes_owner_s4' => '“পার্টনারের জন্য” মেনু থেকে “স্কিম” খুলুন। স্কিমের নাম, শুরু ও শেষের তারিখ, পণ্য, ন্যূনতম পরিমাণ, সুবিধার ধরন আর পার্টনার কী পাবেন, তা লিখুন।',
    'sales_kit_schemes_owner_s5' => '“স্কিম সেভ করুন” চাপুন। চলতি স্কিম পার্টনাররা অর্ডারের সময় দেখতে পান।',
    'sales_kit_schemes_owner_s6' => 'স্কিম বদলাতে “এডিট” চাপুন। কারণ লিখুন। কোনো অর্ডারে ফ্রি পণ্য চলে গেলে শুধু নাম, লেখা আর শেষের তারিখ বদলানো যায়।',
    'sales_kit_schemes_owner_o1' => 'পার্টনাররা শুধু অনুমোদিত ফাইল আর এখন চলছে এমন স্কিম দেখেন।',
    'sales_kit_schemes_owner_o2' => 'পার্টনারের মেনুতে “সেলস কিট” তখনই আসে, যখন তাতে অন্তত একটি ফাইল থাকে।',
    'sales_kit_schemes_owner_t1' => 'পার্টনার কী পাবেন, তা আপনি যেভাবে লিখবেন ঠিক সেভাবেই দেখাবে।',
    'sales_kit_schemes_owner_w1' => 'স্কিমে দাম, অর্ডারের মোট টাকা বা কমিশন বদলায় না।',
    'sales_kit_schemes_owner_w2' => '“ফ্রি পণ্য” বেছে নিলে শর্ত পূরণ করা অর্ডারে সেটি একবার বিনা দামে যোগ হয়। তাতে কোনো কমিশন হয় না। ফ্রি পণ্য না দিলে অফিসকে হাতে সুবিধাটি দিতে হবে।',
    'finance_treasury_s1' => 'মেনু থেকে “ট্রেজারি” খুলুন। “ফান্ড” ট্যাবে প্রতিটি ফান্ডের একটি করে কার্ড দেখবেন।',
    'finance_treasury_s2' => 'একটি কার্ডে চাপুন। কত এসেছে, কত বের হয়েছে আর এখন কত আছে, তিনটিই দেখবেন।',
    'finance_treasury_s3' => '“কোম্পানির লাভ” কার্ডটি দেখুন। যে অংশ কেউ পাননি, যেমন রেফারার বা এরিয়া ডিলার না থাকলে, সেই টাকা এখানে আসে। প্রতিটি লাইনে কারণ লেখা থাকে।',
    'finance_treasury_s4' => 'খরচ করতে ফান্ড খুলে “খরচ করুন” চাপুন। স্টাফ লিখলে অন্য একজন স্টাফ “খরচ, বাজেট ও বাকি কাজ” পাতায় অনুমোদন করবেন। মালিকের ঠিক করা সীমার সমান বা বেশি খরচ মালিকের অপেক্ষায় থাকে। মালিক নিজেই অনুমোদন করতে পারেন।',
    'finance_treasury_s5' => '“অন্যান্য মডিউল” পাতার “ঘটনার খাতা” বাক্সে অর্ডার, টাকা জমা, কমিশন, টাকা তোলা ও স্টকের সব ঘটনা আছে। ফিল্টার দিয়ে একটি ধরন বেছে দেখুন।',
    'finance_treasury_s6' => '“পার্টনারদের টাকা” ট্যাবে প্রতিটি ডিলার ও সাব-ডিলারের এখনকার টাকা ও মোট আয় দেখুন। যা কারও কাজের অপেক্ষায়, তা আছে “খরচ, বাজেট ও বাকি কাজ” ট্যাবে।',
    'finance_treasury_s7' => 'শুধু মালিক “লাভ-ক্ষতির হিসাব” ট্যাব দেখেন। মাস বা তারিখ বেছে দেখুন, বিক্রি থেকে মালের খরচ, কমিশন ও বেতন বাদ দিয়ে কত লাভ বা ক্ষতি।',
    'finance_treasury_o1' => 'প্রতিটি অঙ্কে চাপলে তার পেছনের লাইনগুলো দেখা যায়।',
    'finance_treasury_o2' => 'আপনি জানেন কোম্পানির প্রতিটি টাকা এখন কোথায় আছে।',
