    'finance_policies_simulator_w2' => 'নতুন নিয়মের সাথে মেলাতে আগের সেভ করা ভাগ বদলাবেন না।',
    'payouts_settlements_s1' => 'মেনু থেকে “টাকা তোলার অনুরোধ” খুলুন। “যা বাকি” ফিল্টারে দেরি হওয়া ও আটকে থাকা অনুরোধ দেখবেন।',
    'payouts_settlements_s2' => 'অনুরোধের পাশে “যাচাই” চাপুন। পার্টনারের অবস্থা, ব্যালেন্স, নম্বর ও NID দেখে নিন।',
    'payouts_settlements_s3' => 'সব ঠিক থাকলে “অনুরোধ অনুমোদন” চাপুন। না হলে “অনুরোধ নামঞ্জুর” চাপুন ও কারণ লিখুন।',
    'payouts_settlements_s4' => 'কে টাকা পাঠাবেন তা বেছে নিন। নিজে পাঠালে “আমি পাঠাব” চাপুন।',
    'payouts_settlements_s5' => 'পার্টনারের চাওয়া নম্বরে টাকা পাঠান। তারপর “পেমেন্ট রেকর্ড করুন” চেপে লেনদেন নম্বর ও রসিদের ছবি দিন।',
    'payouts_settlements_s6' => 'রসিদ হাতে না থাকলে “টাকা পাঠিয়েছি, রসিদ পরে দেব” বেছে নিন। পরে “রসিদ যোগ করুন” চাপুন।',
    'payouts_settlements_s7' => 'মাসের শেষে মেনু থেকে “মাস শেষ: কমিশন ও বেতন দিন” খুলুন। প্রতি মাসের বেতন ও রয়্যালটি সাধারণত এক ঘণ্টার মধ্যে নিজে বন্ধ হয়। পুরনো মাসে “এই মাস বন্ধ করুন” চাপুন।',
    'payouts_settlements_o1' => 'প্রতিটি পেমেন্টে কে দিলেন, কখন দিলেন আর রসিদ লেখা থাকে।',
    'payouts_settlements_o2' => 'বন্ধ হওয়া মাসে কত টাকা পার্টনারদের গেছে, তা দেখা যায়।',
    'payouts_settlements_t1' => 'পার্টনার অপেক্ষার অনুরোধ নিজে বাতিল করতে পারেন। তখন টাকা ওয়ালেটে ফিরে যায়। মালিক একাই তৈরি, অনুমোদন ও পরিশোধ করতে পারেন।',
    'payouts_settlements_t2' => 'ফোন নম্বর বা পাসওয়ার্ড বদলের পর সাধারণত ২ ঘণ্টা টাকা তোলা যায় না। এটা নিরাপত্তার জন্য।',
    'payouts_settlements_w1' => 'অ্যাকাউন্ট নম্বর না মিলিয়ে কখনো টাকা পাঠাবেন না।',
    'payouts_settlements_w2' => 'পার্টনারের অ্যাকাউন্ট স্থগিত হলে অনুরোধ আটকে যায়। তখন অনুমোদন বা পেমেন্ট করা যায় না।',
    'ledger_audit_reports_s1' => 'মেনু থেকে “অন্যান্য মডিউল” খুলে “ঘটনার খাতা” বাক্সে চাপুন। কে কী অনুমোদন করল আর কখন, তা এখানে দেখা যায়।',
    'ledger_audit_reports_s2' => 'নাম, অর্ডার নম্বর বা তারিখ দিয়ে খুঁজুন।',
