    'ledger_audit_reports_s4' => 'কে কী বদলেছেন দেখতে “সেটিংস” থেকে “কাজের রেকর্ড” খুলুন।',
    'ledger_audit_reports_o1' => 'একটি অর্ডারের দেওয়া থেকে ডেলিভারি ও কমিশন পর্যন্ত পুরোটা দেখা যায়।',
    'ledger_audit_reports_o2' => 'কোনো বদল কে করেছেন ও কখন করেছেন, তা জানা যায়।',
    'ledger_audit_reports_t1' => 'অর্ডার নম্বর দিয়ে খুঁজলে ওই অর্ডারের সবকিছু একসাথে আসে।',
    'ledger_audit_reports_w1' => 'এখানকার লেখা বদলানো বা মোছা যায় না।',
    'financial_activation_gates_s1' => 'লাইভ বন্ধ থাকলে ক্যালকুলেটর ও পার্টনারদের অনেক পাতা চলে। কিন্তু আসল কোনো পাওনা বা আয় জমা হয় না।',
    'financial_activation_gates_s2' => 'চালুর আগে সেটিংসের “শুরুর ব্যালেন্স যাচাই” পাতা খুলুন। সবকিছু প্রস্তুত কি না, সেখানে দেখুন।',
    'financial_activation_gates_s3' => 'পুরনো কোনো ব্যালেন্স না থাকলে মালিকের হোম পেজে “হিসাব শুরু করুন” কার্ডটি খুলুন। টিক দিয়ে “শূন্য থেকে হিসাব শুরু করুন” চাপুন।',
    'financial_activation_gates_s4' => 'মালিক একাই শুরুর ব্যালেন্স ও কমিশনের নিয়ম যাচাই করতে পারেন। স্টাফ তৈরি করলে মালিক বা অন্য অনুমোদনকারী যাচাই করেন।',
    'financial_activation_gates_s5' => 'লাইভ চালু করুন শুধু ঠিক করা নিয়মে। তাড়াহুড়ো করে সার্ভারে বদলাবেন না।',
    'financial_activation_gates_s6' => 'চালুর দিন ও সময় লিখে ডিলারদের নোটিশ দিন। প্রথম দিন খাতা ও পেমেন্টের দিকে বিশেষ নজর রাখুন।',
    'financial_activation_gates_o1' => 'টাকার হিসাব লাইভ নাকি ট্রায়ালে আছে, সবাই জানে।',
    'financial_activation_gates_o2' => 'চালুর আগে লিখিত অনুমোদন ও প্রস্তুতির প্রমাণ থাকে।',
    'financial_activation_gates_o3' => 'সাপোর্ট স্টাফ বুঝিয়ে বলতে পারেন টাকার হিসাব কেন বন্ধ। তাঁরা নিজে থেকে চালুর তারিখ বলেন না।',
    'financial_activation_gates_t1' => 'ডেমো সিস্টেমে লাইভ টাকার হিসাব সবসময় বন্ধ রাখুন।',
    'financial_activation_gates_t2' => 'চালুর সময় ব্যাকআপ ঠিক আছে কি না দেখে নিন। থামানোর পরিকল্পনাও আগে ঠিক রাখুন।',
    'financial_activation_gates_w1' => 'তথ্য অসম্পূর্ণ থাকলে শুধু ব্যালেন্স ঠিক করতে লাইভ চালু করবেন না।',
    'financial_activation_gates_w2' => 'আসল ব্যবসার সিস্টেমে কখনো ডেমো তথ্য চালাবেন না।',
    'financial_activation_gates_w3' => 'অপেক্ষার দিন শেষ হওয়া কমিশন নিজে থেকে দেওয়ার সুইচ আলাদা। শুধু মালিক সেটি বদলান।',
    'accounting_statements_s1' => '“ট্রেজারি” খুলে “অর্ডারের হিসাব” ট্যাবে যান। যে সময়ের হিসাব চান, সেই তারিখ বেছে নিন।',
    'accounting_statements_s2' => '“ফাইল নামান” চাপুন।',
    'accounting_statements_s3' => '“লাভ-ক্ষতির হিসাব”, “ব্যালেন্স শিট” বা “ট্রায়াল ব্যালেন্স” বেছে নিন।',
    'accounting_statements_o1' => 'ফাইলে ঠিক আপনার বেছে নেওয়া তারিখের হিসাব থাকে।',
    'accounting_statements_t1' => 'প্রতি মাসে ফাইলগুলো হিসাবরক্ষককে দিন।',
    'accounting_statements_w1' => 'এই ফাইল এখনো পুরো হিসাব নয়। বিক্রি ও কেনার কিছু লাইন অন্য নথি থেকে আসে, কিছু আনুমানিক। একে অডিট করা হিসাব বলবেন না।',
    'accounting_statements_w2' => 'ফাইলে কোম্পানির হিসাব আছে। এটি গোপন রাখুন।',
    'menu_office_s1' => 'ওপরের সারি: “ড্যাশবোর্ড”, “অর্ডার”, “অর্ডারের টাকা যাচাই”, “ডেলিভারি”, “মেসেজ ও সাপোর্ট”।',
    'menu_office_s2' => 'টাকার সারি: “ট্রেজারি”, “টাকা তোলার অনুরোধ”, “মাস শেষ: কমিশন ও বেতন দিন”।',
    'menu_office_s3' => 'কাজের সারি: “পণ্য ও স্টক”, “ডিলার ও সাব-ডিলার”, “নতুন পার্টনারের আবেদন”, “রিপোর্ট”, “প্রেসক্রিপশন”।',
    'menu_office_s4' => 'কমিশনের নিয়ম ও হার, ঘটনার খাতা, স্কিম, প্রশিক্ষণ, স্টাফ, ওয়েবসাইট আর ব্যবহারের নির্দেশিকা এখন “অন্যান্য মডিউল” পাতায় আছে।',
    'menu_office_s5' => '“সেটিংস” সবার নিচে। টাকা, এলাকা ও সিস্টেমের নিয়ম সেখানে।',
    'menu_office_s6' => 'একটি সারিতে কয়েকটি পাতা থাকলে পাতার ওপরে ছোট ট্যাব দেখবেন। ট্যাবে চাপ দিয়ে পাতা বদলান।',
    'menu_office_o1' => 'যে পাতার অনুমতি আছে, শুধু সেটাই মেনুতে দেখাবে।',
    'menu_office_t1' => '“মেনু খুঁজুন” ঘরে পাতার নাম লিখলে সরাসরি সেই পাতায় যাবেন।',
    'menu_office_w1' => 'মেনুতে কোনো পাতা না থাকলে সেটা নষ্ট নয়। আপনার সেই পাতার অনুমতি নেই। মালিককে বলুন।',
    'settings_home_s1' => '“সেটিংস” খুলুন। “টাকা”, “এলাকা ও পার্টনার” ও “সিস্টেম” নামে তিন ভাগ পাবেন।',
    'settings_home_s2' => 'টাকা: টাকা তোলার নিয়ম, বিকাশ ও ব্যাংকের নম্বর, শুরুর টাকার হিসাব মেলানো।',
    'settings_home_s3' => 'এলাকা ও পার্টনার: এলাকার কোড, পার্টনারের ড্যাশবোর্ডে কী দেখাবে, একই ব্যক্তির দুই অ্যাকাউন্ট আছে কিনা।',
    'settings_home_s4' => 'সিস্টেম: লগইনের নিয়ম, কারণ লেখার নিয়ম, এসএমএস ও কুরিয়ারের সংযোগ, কুরিয়ারের এলাকা।',
    'settings_home_s5' => 'সিস্টেমে আরও আছে: এক্সেল থেকে তথ্য আনা, কাজের রেকর্ড, তথ্যের অনুরোধ, পুরোনো তথ্য মোছা ও সাইটের সমস্যার তালিকা।',
    'settings_home_s6' => 'একটি বাক্স খুলুন, দরকারি ঘর বদলান, তারপর “সেভ করুন” চাপুন।',
    'settings_home_o1' => 'খোলার আগেই বাক্সের লেখা পড়ে বুঝবেন সেটা কী করে।',
    'settings_home_t1' => 'যে বাক্স দেখছেন না, সেটা আপনার কাজের বাইরে। নষ্ট নয়।',
    'settings_home_w1' => 'সেভ করার আগে নিশ্চিত হন। এখানকার বদল একসাথে সবার ওপর পড়ে।',
    'office_more_pages_s1' => '“অন্যান্য মডিউল” খুলুন। যে বাক্সে চাপবেন, সেই পাতা খুলবে।',
    'office_more_pages_s2' => 'পার্টনারদের জন্য: “স্কিম”, “প্রতিযোগিতা”, “সেলস কিট”, “প্রশিক্ষণ”, “মিটিং” ও “চুক্তি”।',
    'office_more_pages_s3' => 'স্টাফ ও লোকজন: “স্টাফ তালিকা”, “স্টাফ বেতন”, “এসআর এলাকা ও টার্গেট”, “মাঠের বিক্রি”, “পদ ও অনুমতি”।',
    'office_more_pages_s4' => 'স্টাফ তালিকায় নতুন স্টাফের নাম, ফোন, পদ ও শাখা দিন। সংরক্ষণের পর প্রথম পাসওয়ার্ড একবার দেখাবে। লিখে নিয়ে তাঁকে দিন।',
    'office_more_pages_s5' => 'ওয়েবসাইট: “ওয়েবসাইট সাজান”, “পাতার লেখা”, “বিশ্বাসযোগ্যতার পাতা”, “ভিডিও”, “মতামত” ও “ওয়েবসাইটের ভিজিটর” (এই পাতাতেই দেখা যায় কোন ডিলার ও সাব-ডিলার এখন অনলাইনে, তাঁদের শেষ আইপি, ডিভাইস ও ব্রাউজার সহ)।',
    'office_more_pages_s6' => 'মতামত অনুমোদন করলে সেটি ওয়েবসাইটে দেখা যায়।',
    'office_more_pages_s7' => 'চিকিৎসা: “প্রেসক্রিপশন”।',
    'office_more_pages_s8' => 'নতুন আবেদন “নতুন পার্টনারের আবেদন” মেনু থেকে দেখুন। আবেদনের নম্বর, বয়স ও আগের অ্যাকাউন্ট সেখানেই মিলিয়ে নিন।',
    'office_more_pages_s9' => 'টাকা ও হিসাব: “কমিশনের নিয়ম ও হার” আর “ঘটনার খাতা”। ঘটনার খাতায় দেখা যায় কে কী অনুমোদন করল আর কখন।',
    'office_more_pages_s10' => 'সাহায্য: “ব্যবহারের নির্দেশিকা ও ট্যুর”। এতে চাপলে নির্দেশিকা খুলবে।',
    'office_more_pages_o1' => 'কম লাগার সব পাতা এক জায়গায় পাবেন।',
    'office_more_pages_t1' => 'যেকোনো পাতায় সাহায্যের চিহ্নে চাপলে সেই পাতার নিয়ম আগে দেখাবে।',
    'office_more_pages_w1' => 'আবেদন অনুমোদন করলে আসল অ্যাকাউন্ট তৈরি হয়। আগে কাগজপত্র মিলিয়ে নিন।',
    'menu_partner_s1' => '“হোম” আপনার ড্যাশবোর্ড। এখানে আপনার ছবি, মোবাইল, কোড, র‍্যাংক, মোট আয়, বর্তমান ব্যালেন্স, এই মাসের কেনা, টার্গেট পূরণে বাকি আর আপনার দায়িত্বের এলাকা দেখবেন। ওপরের “সাইন আউট” বাটনে চেপে (ফোনে মেনু খুলে ওপরের “সাইন আউট”) বেরিয়ে যেতে পারেন।',
    'menu_partner_s2' => '“নতুন অর্ডার” থেকে অর্ডার শুরু করুন। পুরোনো অর্ডার ও ডেলিভারি “আমার অর্ডার”-এ।',
    'menu_partner_s3' => '“ওয়ালেট” একটাই পাতা। কত টাকা আছে, কোথা থেকে এসেছে আর কত তুলেছেন, সব এখানে।',
    'menu_partner_s4' => 'সাব-ডিলারের বেতনের হিসাবও “ওয়ালেট”-এ আছে। তালিকার ফিল্টারে “বেতন” বেছে নিন।',
    'menu_partner_s5' => '“আমার টিম ও গ্রাহক”-এ আছে টিম, গ্রাহক, র‍্যাঙ্ক, সেরা বিক্রেতা ও প্রতিযোগিতা। সাব-ডিলারের সারির নাম “আমার কাস্টমার”; তাতে আছে গ্রাহক, সেরা বিক্রেতা ও প্রতিযোগিতা।',
    'menu_partner_s6' => '“অন্যান্য মডিউল”-এ আছে প্রশিক্ষণ, মিটিং, সেলস কিট ও মতামত দিন। চুক্তি আছে “আমার প্রোফাইল” বা “আমার অ্যাকাউন্ট”-এর ভেতরে।',
    'menu_partner_s7' => '“অফিসে যোগাযোগ”-এ আছে মেসেজ, নোটিশ ও সাহায্য।',
    'menu_partner_s8' => '“আমার প্রোফাইল”-এ আছে আপনার পুরো তথ্য (শুধু দেখার জন্য) ও নিরাপত্তা। পাসওয়ার্ড এখানে বদলান। “আমার অ্যাকাউন্ট”-এ আপনার সব আয় আলাদা আলাদা লাইনে দেখবেন। “প্রেসক্রিপশন” সবসময় মেনুতে থাকে, যাঁর অনুমতি আছে তাঁর জন্য।',
    'menu_partner_o1' => 'কোনো পাতা না খুঁজে সরাসরি পেয়ে যাবেন।',
    'menu_partner_t1' => '“মেনু খুঁজুন” ঘরে পাতার নাম লিখলে সরাসরি সেই পাতায় যাবেন।',
    'menu_partner_w1' => 'কোনো পাতা মেনুতে না থাকলে সেটা আপনার অ্যাকাউন্টের জন্য বন্ধ আছে। অফিসে জিজ্ঞেস করুন।',
